### 5. **glTF Model Loading & Rendering**

**Location:** [elements/ui/elements.tsx](elements/ui/elements.tsx#L18054)

```typescript
const Gltf: React.FC<GltfProps> = ({ src, roughness = 0.8, metalness = 0 }) => {
  const { scene } = useGLTF(src);
  const plasterColor = new THREE.Color(getComputedColorForGltf("--plaster"));
  const plasterEdgeColor = new THREE.Color(getComputedColorForGltf("--plaster-edge"));

  const clonedScene = useMemo(() => {
    const cloned = scene.clone();
    const plasterMaterial = new THREE.MeshStandardMaterial({
      color: plasterColor,
      flatShading: false,
      metalness,
      roughness,
    });
    const edgeMaterial = new THREE.LineBasicMaterial({ color: plasterEdgeColor });

    cloned.traverse((child) => {
      if ((child as any).isMesh) {
        (child as any).raycast = THREE.Mesh.prototype.raycast;
        if (Array.isArray((child as any).material)) {
          (child as any).material = (child as any).material.map(() => plasterMaterial.clone());
        } else {
          (child as any).material = plasterMaterial.clone();
        }
      } else if (child instanceof THREE.Line || ...) {
        (child as any).material = edgeMaterial.clone();
      }
    });
    return cloned;
  }, [scene, plasterColor, plasterEdgeColor, roughness, metalness]);

  return <primitive object={clonedScene} />;
};
```

**Process:**
1. Load glTF using `useGLTF()` hook from drei
2. Clone the scene to modify materials
3. Apply theme colors (--plaster, --plaster-edge CSS variables)
4. Set MeshStandardMaterial for surfaces
5. Set LineBasicMaterial for edges
6. Render as primitive object

---

### 6. **Piece Rendering in Design 3D Scene**

**Location:** [compose/sketchpad/index.tsx](compose/sketchpad/index.tsx#L37565) (ModelPiece component)

**Piece Transformation Pipeline:**
```typescript
const ModelPiece: FC<ModelPieceProps> = () => {
  const piece = usePiece() as Piece;
  const diffedPiece = useDiffedPiece() as Piece;
  const isSelected = useIsPieceSelected();
  const isHovered = useIsPieceTransitiveHovered();
  const flatPlane = useFlatPiecePlane();

  const isConnectedChild = useIsConnectedPiece();
  const originalPlane = isConnectedChild ? flatPlane : piece.plane || flatPlane;
  const diffedPlane = isConnectedChild ? flatPlane : diffedPiece.plane || flatPlane;

  // Convert Compose plane to Three.js matrix
  const originalMatrix = useMemo(() => {
    if (!originalPlane) return null;
    const planeMatrix = planeToMatrix(originalPlane as Plane);
    const threeMatrix = new THREE.Matrix4()
      .multiplyMatrices(toThreeRotation(), planeMatrix);
    return threeMatrix;
  }, [originalPlane]);

  const diffedMatrix = useMemo(() => {
    if (!diffedPlane || !hasDiff) return null;
    const planeMatrix = planeToMatrix(diffedPlane as Plane);
    const threeMatrix = new THREE.Matrix4()
      .multiplyMatrices(toThreeRotation(), planeMatrix);
    return threeMatrix;
  }, [diffedPlane, hasDiff]);

  // Decompose matrix into position, rotation, scale
  const transformProps = useMemo(() => {
    const matrix = diffedMatrix || originalMatrix;
    if (!matrix || !originalPlane) return null;
    const position = new THREE.Vector3();
    const quaternion = new THREE.Quaternion();
    const scale = new THREE.Vector3();
    matrix.decompose(position, quaternion, scale);
    return { position, quaternion, scale };
  }, [diffedMatrix, originalMatrix, originalPlane]);

  // Render with transformation
  const pieceMatrix = diffedMatrix || originalMatrix;
  return (
    <>
      {originalMeshContent}
      {pieceMatrix && (
        <group userData={userData} matrix={pieceMatrix} matrixAutoUpdate={false}>
          {diffedMeshContent}
        </group>
      )}
    </>
  );
};
```

