### 8. **3D Scene Rendering Loop**

**Design Scene Content:** [compose/sketchpad/index.tsx](compose/sketchpad/index.tsx#L37800) (ModelDesign component)

```typescript
const ModelDesign: FC = () => {
  const design = useDesign() as Design;
  const { showPieces } = useDesignFilters();

  return (
    <DreiSelect box multiple onChange={onChange}>
      <group>
        {showPieces &&
          design?.pieces?.map((piece: Piece) => (
